// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Send a magic-link email to bind an address to the current user
	// (POST /auth/email/bind/request)
	RequestEmailBind(ctx context.Context, request RequestEmailBindRequestObject) (RequestEmailBindResponseObject, error)
	// Create a fresh Bot-scoped TAT transport
	// (POST /auth/federation/bots/{bot_id}/tat/session)
	CreateFederationTatSession(ctx context.Context, request CreateFederationTatSessionRequestObject) (CreateFederationTatSessionResponseObject, error)
	// Validate a federation authorization request
	// (GET /auth/federation/context)
	GetFederationContext(ctx context.Context, request GetFederationContextRequestObject) (GetFederationContextResponseObject, error)
	// Exchange a handoff ticket for an opaque delegated session
	// (POST /auth/federation/exchange)
	ExchangeFederationTicket(ctx context.Context, request ExchangeFederationTicketRequestObject) (ExchangeFederationTicketResponseObject, error)
	// Issue a short-lived federation handoff ticket
	// (POST /auth/federation/tickets)
	IssueFederationTicket(ctx context.Context, request IssueFederationTicketRequestObject) (IssueFederationTicketResponseObject, error)
	// Activate the current authenticated user with an invite code
	// (POST /auth/invite/activate)
	ActivateInviteCode(ctx context.Context, request ActivateInviteCodeRequestObject) (ActivateInviteCodeResponseObject, error)
	// Validate an invite code
	// (POST /auth/invite/validate)
	ValidateInviteCode(ctx context.Context, request ValidateInviteCodeRequestObject) (ValidateInviteCodeResponseObject, error)
	// Trigger forgot-password flow placeholder
	// (POST /auth/password/forgot)
	ForgotPassword(ctx context.Context, request ForgotPasswordRequestObject) (ForgotPasswordResponseObject, error)
	// Sign in with email and password
	// (POST /auth/password/sign-in)
	SignInWithPassword(ctx context.Context, request SignInWithPasswordRequestObject) (SignInWithPasswordResponseObject, error)
	// Register with email and password
	// (POST /auth/password/sign-up)
	SignUpWithPassword(ctx context.Context, request SignUpWithPasswordRequestObject) (SignUpWithPasswordResponseObject, error)
	// List the current user's signed payment cards
	// (GET /auth/payment-methods)
	ListPaymentMethods(ctx context.Context, request ListPaymentMethodsRequestObject) (ListPaymentMethodsResponseObject, error)
	// Create a hosted card signing order for the current user
	// (POST /auth/payment-methods/sign-orders)
	CreatePaymentMethodSignOrder(ctx context.Context, request CreatePaymentMethodSignOrderRequestObject) (CreatePaymentMethodSignOrderResponseObject, error)
	// Delete one of the current user's non-default signed cards
	// (DELETE /auth/payment-methods/{contractCode})
	DeletePaymentMethod(ctx context.Context, request DeletePaymentMethodRequestObject) (DeletePaymentMethodResponseObject, error)
	// Set one of the current user's signed cards as default
	// (PUT /auth/payment-methods/{contractCode}/default)
	SetDefaultPaymentMethod(ctx context.Context, request SetDefaultPaymentMethodRequestObject) (SetDefaultPaymentMethodResponseObject, error)
	// Get the current user profile
	// (GET /auth/profile)
	GetProfile(ctx context.Context, request GetProfileRequestObject) (GetProfileResponseObject, error)
	// Update the current user profile
	// (PUT /auth/profile)
	UpdateProfile(ctx context.Context, request UpdateProfileRequestObject) (UpdateProfileResponseObject, error)
	// Redirect to the current user's avatar asset
	// (GET /auth/profile/avatar)
	GetProfileAvatar(ctx context.Context, request GetProfileAvatarRequestObject) (GetProfileAvatarResponseObject, error)
	// Upload and replace the current user's avatar
	// (PUT /auth/profile/avatar)
	UpdateProfileAvatar(ctx context.Context, request UpdateProfileAvatarRequestObject) (UpdateProfileAvatarResponseObject, error)
	// Start a FaceID real-name verification attempt
	// (POST /auth/realname/faceid/attempts)
	StartRealnameFaceIDAttempt(ctx context.Context, request StartRealnameFaceIDAttemptRequestObject) (StartRealnameFaceIDAttemptResponseObject, error)
	// Read the current recoverable FaceID attempt for the authenticated user
	// (GET /auth/realname/faceid/attempts/current)
	GetCurrentRealnameFaceIDAttempt(ctx context.Context, request GetCurrentRealnameFaceIDAttemptRequestObject) (GetCurrentRealnameFaceIDAttemptResponseObject, error)
	// Reconcile and read an owned FaceID attempt
	// (GET /auth/realname/faceid/attempts/{attemptId})
	GetRealnameFaceIDAttempt(ctx context.Context, request GetRealnameFaceIDAttemptRequestObject) (GetRealnameFaceIDAttemptResponseObject, error)
	// Synchronize an attempt to Shadow and activate final verification
	// (POST /auth/realname/faceid/attempts/{attemptId}/finalize)
	FinalizeRealnameFaceIDAttempt(ctx context.Context, request FinalizeRealnameFaceIDAttemptRequestObject) (FinalizeRealnameFaceIDAttemptResponseObject, error)
	// Send a Shadow verification code to the current phone for a FaceID attempt
	// (POST /auth/realname/faceid/attempts/{attemptId}/send-phone-code)
	SendRealnameFaceIDPhoneCode(ctx context.Context, request SendRealnameFaceIDPhoneCodeRequestObject) (SendRealnameFaceIDPhoneCodeResponseObject, error)
	// Verify the current phone through Shadow binding for a FaceID attempt
	// (POST /auth/realname/faceid/attempts/{attemptId}/verify-phone)
	VerifyRealnameFaceIDPhone(ctx context.Context, request VerifyRealnameFaceIDPhoneRequestObject) (VerifyRealnameFaceIDPhoneResponseObject, error)
	// Receive a Tencent FaceID browser redirect
	// (GET /auth/realname/faceid/callback)
	HandleRealnameFaceIDCallback(ctx context.Context, request HandleRealnameFaceIDCallbackRequestObject) (HandleRealnameFaceIDCallbackResponseObject, error)
	// Retry syncing current user's verified real-name identity to the account system
	// (POST /auth/realname/sync/retry)
	RetryRealnameSync(ctx context.Context, request RetryRealnameSyncRequestObject) (RetryRealnameSyncResponseObject, error)
	// Verify current user's real-name identity
	// (POST /auth/realname/verify)
	VerifyRealname(ctx context.Context, request VerifyRealnameRequestObject) (VerifyRealnameResponseObject, error)
	// Verify current user's phone as the third real-name factor
	// (POST /auth/realname/verify-phone)
	VerifyRealnamePhone(ctx context.Context, request VerifyRealnamePhoneRequestObject) (VerifyRealnamePhoneResponseObject, error)
	// Delete the current session
	// (DELETE /auth/session)
	SignOut(ctx context.Context, request SignOutRequestObject) (SignOutResponseObject, error)
	// Get the current session
	// (GET /auth/session)
	GetCurrentSession(ctx context.Context, request GetCurrentSessionRequestObject) (GetCurrentSessionResponseObject, error)
	// Get current user's Lightvela shadow binding status
	// (GET /auth/shadow/binding)
	GetShadowBinding(ctx context.Context, request GetShadowBindingRequestObject) (GetShadowBindingResponseObject, error)
	// Retry current user's failed Lightvela shadow binding
	// (POST /auth/shadow/binding/retry)
	RetryShadowBinding(ctx context.Context, request RetryShadowBindingRequestObject) (RetryShadowBindingResponseObject, error)
	// Send an SMS verification code
	// (POST /auth/sms/send)
	SendSmsCode(ctx context.Context, request SendSmsCodeRequestObject) (SendSmsCodeResponseObject, error)
	// Verify SMS code and create a session
	// (POST /auth/sms/verify)
	VerifySmsCode(ctx context.Context, request VerifySmsCodeRequestObject) (VerifySmsCodeResponseObject, error)
	// Create a one-time Tencent Cloud console login redirect for the current user
	// (POST /auth/tencent-cloud/redirect)
	CreateTencentCloudRedirect(ctx context.Context, request CreateTencentCloudRedirectRequestObject) (CreateTencentCloudRedirectResponseObject, error)
}

